// Producers may run NEWER schema versions than this service.
func (a *Archiver) Store(ctx context.Context, e *pb.OrderEvent) error {
	payload, err := protojson.Marshal(e) // human-readable archive
	if err != nil {
		return err
	}
	_, err = a.db.ExecContext(ctx,
		`INSERT INTO order_archive (order_id, payload) VALUES ($1, $2)`,
		e.OrderId, payload)
	return err
}

func (a *Archiver) Replay(payload []byte, sink func(*pb.OrderEvent) error) error {
	var e pb.OrderEvent
	if err := protojson.Unmarshal(payload, &e); err != nil {
		return err
	}
	if e.Rating != 0 { // skip unrated orders
		recordRating(e.OrderId, e.Rating)
	}
	return sink(&e)
}
